/**
 * The runtime's real /live answers (live.json), generated by
 * scripts/agentLive/generateLiveFixtures.mjs from authority-one-runtime
 * agent-live/integration (commit in `LIVE.source`). Nothing here is
 * hand-written: re-run the generator to refresh it.
 *
 * The tokens are signed with the runtime test world's synthetic region secret
 * and name synthetic DIDs only.
 */
import live from './live.json'

type Reply = {status: number; body: Record<string, unknown>}

export const LIVE = live as unknown as {
  source: {repo: string; ref: string; commit: string}
  device: {seedHex: string; publicKey: string}
  owner: {did: string; agentDid: string; otherAgentDid: string}
  responses: Record<string, Reply>
  media: Record<string, {ok: boolean; reason?: string; identity?: string}>
  proofs: Record<string, string>
}

export const R = LIVE.responses

export function reply(name: string): Reply {
  const r = R[name]
  if (!r) throw new Error(`live.json has no response ${name}`)
  return r
}

/** A runtime join token from the fixtures (consent, token or camera reply). */
export const tokenOf = (name: string) => String(reply(name).body.token)

export const OWNER_DID = LIVE.owner.did
export const AGENT_DID = LIVE.owner.agentDid
export const AGENT_HANDLE = 'agent.pds.authority-one.test'
export const SID = String(reply('startAwaitingConsent').body.sid)

export const DEVICE_SEED = Uint8Array.from(
  LIVE.device.seedHex.match(/../g)!.map(h => parseInt(h, 16)),
)
